import Foundation

// Alle 70 Rezepte (je 1 Portion). Neue Rezepte einfach im gleichen Format ergänzen.
enum RecipeData {
    static let all: [Recipe] = {
        do {
            return try JSONDecoder().decode([Recipe].self, from: Data(json.utf8))
        } catch {
            print("Rezepte konnten nicht geladen werden: \(error)")
            return []
        }
    }()

    private static let json = #"""
[
{"id": "overnight-oats-mit-beeren", "cat": "fruehstueck", "ty": "veggie", "kcal": 300, "t": "5 Min. + über Nacht", "name": "Overnight Oats mit Beeren", "g": [["Zutaten", [[40, "g", "Haferflocken"], [150, "g", "Magerjoghurt oder Skyr"], [50, "ml", "Milch"], [1, "Handvoll", "Beeren"], [1, "TL", "Chiasamen"]]]], "s": [["Vorbereiten", "Ein verschließbares Glas oder eine Schüssel (ca. 400 ml) bereitstellen. Haferflocken, Joghurt bzw. Skyr und Milch hineingeben."], ["Verrühren", "Alles gründlich verrühren, bis keine trockenen Haferflocken mehr zu sehen sind. Die Masse sollte noch etwas flüssiger sein als gewünscht, da die Flocken quellen."], ["Quellen lassen", "Das Glas verschließen und über Nacht, mindestens aber 4 Stunden, in den Kühlschrank stellen."], ["Toppen", "Morgens einmal umrühren. Ist es zu fest, 1–2 EL Milch unterrühren. Beeren waschen, abtropfen lassen und mit den Chiasamen darauf verteilen."], ["Tipp", "Hält sich im Kühlschrank bis zu 2 Tage. Ideal zum Mitnehmen ins Büro."]]},
{"id": "gemuese-omelett", "cat": "fruehstueck", "ty": "veggie", "kcal": 250, "t": "10 Min.", "name": "Gemüse-Omelett", "g": [["Zutaten", [[2, "", "Eier"], [1, "Handvoll", "Spinat"], [0.25, "", "Paprika"], [0.5, "", "Tomate"], [0.25, "", "Zwiebel"], [1, "TL", "Öl"], [null, "", "Salz, Pfeffer, Kräuter"]]]], "s": [["Gemüse schneiden", "Zwiebel fein würfeln, Paprika in kleine Würfel schneiden, Tomate entkernen und würfeln. Spinat waschen und gut abtropfen lassen."], ["Eier verquirlen", "Eier in einer Schüssel mit einer Gabel kräftig verquirlen und mit Salz und Pfeffer würzen."], ["Anbraten", "Öl in einer beschichteten Pfanne (ca. 20 cm) bei mittlerer Hitze erwärmen. Zwiebel und Paprika 2–3 Minuten andünsten, dann Tomate und Spinat zugeben und rühren, bis der Spinat zusammenfällt."], ["Stocken lassen", "Gemüse gleichmäßig verteilen und die Eier darübergießen. Bei mittlerer bis niedriger Hitze 4–5 Minuten stocken lassen, ohne zu rühren. Mit einem Deckel geht es schneller."], ["Servieren", "Wenn die Oberfläche fast fest ist, Omelett mit dem Pfannenwender zusammenklappen, auf einen Teller gleiten lassen und mit frischen Kräutern bestreuen."]]},
{"id": "skyr-bowl-mit-apfel-und-zimt", "cat": "fruehstueck", "ty": "veggie", "kcal": 250, "t": "5 Min.", "name": "Skyr-Bowl mit Apfel und Zimt", "g": [["Zutaten", [[200, "g", "Skyr"], [0.5, "", "Apfel"], [0.5, "TL", "Zimt"], [3, "", "Walnusshälften"]]]], "s": [["Skyr cremig rühren", "Skyr in eine Schale geben und kurz glatt rühren. Ist er sehr fest, 1–2 EL Wasser oder Milch unterrühren."], ["Apfel vorbereiten", "Apfel waschen, entkernen und in kleine Würfel schneiden. Die Schale bleibt dran, sie liefert Ballaststoffe."], ["Walnüsse rösten", "Walnüsse grob hacken und in einer Pfanne ohne Fett 2 Minuten anrösten, bis sie duften. Das macht sie aromatischer."], ["Anrichten", "Apfelwürfel auf dem Skyr verteilen, mit Zimt bestäuben und die Walnüsse darüberstreuen."]]},
{"id": "vollkornbrot-mit-huettenkaese", "cat": "fruehstueck", "ty": "veggie", "kcal": 280, "t": "5 Min.", "name": "Vollkornbrot mit Hüttenkäse", "g": [["Zutaten", [[2, "Scheiben", "Vollkornbrot"], [100, "g", "körniger Frischkäse (Hüttenkäse)"], [0.25, "", "Gurke"], [3, "", "Radieschen"], [null, "", "Schnittlauch, Pfeffer"]]]], "s": [["Brot vorbereiten", "Vollkornbrot nach Wunsch kurz toasten, dann wird es knuspriger und hält den Belag besser."], ["Gemüse schneiden", "Gurke und Radieschen waschen und in dünne Scheiben schneiden. Schnittlauch in feine Röllchen schneiden."], ["Bestreichen", "Hüttenkäse gleichmäßig auf beide Brotscheiben verteilen."], ["Belegen und würzen", "Gurken- und Radieschenscheiben dachziegelartig darauflegen, mit Schnittlauch bestreuen und mit frisch gemahlenem Pfeffer würzen."]]},
{"id": "gruener-smoothie", "cat": "fruehstueck", "ty": "veggie", "kcal": 200, "t": "5 Min.", "name": "Grüner Smoothie", "g": [["Zutaten", [[1, "Handvoll", "Spinat"], [0.5, "", "Banane"], [50, "g", "Ananas"], [150, "ml", "Mandelmilch (ungesüßt)"], [1, "EL", "Haferflocken"]]]], "s": [["Zutaten vorbereiten", "Spinat gründlich waschen. Banane schälen und in Stücke brechen. Ananas schälen und würfeln (oder TK-Ananas verwenden)."], ["Einfüllen", "Zuerst die Mandelmilch in den Mixer geben, dann Spinat, Banane, Ananas und Haferflocken. So läuft der Mixer leichter an."], ["Mixen", "Auf höchster Stufe 30–60 Sekunden pürieren, bis keine Spinatstückchen mehr zu sehen sind."], ["Anpassen", "Zu dick? Etwas Wasser zugeben und kurz nachmixen. Für einen kühlen Smoothie gefrorene Banane oder ein paar Eiswürfel verwenden. Sofort trinken."]]},
{"id": "ruehrei-mit-avocado-toast", "cat": "fruehstueck", "ty": "veggie", "kcal": 350, "t": "10 Min.", "name": "Rührei mit Avocado-Toast", "g": [["Zutaten", [[1, "Scheibe", "Vollkorntoast"], [0.25, "", "Avocado"], [2, "", "Eier"], [5, "", "Kirschtomaten"], [null, "", "Salz, Pfeffer, Chiliflocken"]]]], "s": [["Toast rösten", "Vollkorntoast im Toaster goldbraun rösten."], ["Avocado zerdrücken", "Avocado mit einem Löffel aus der Schale lösen, mit einer Gabel grob zerdrücken und mit Salz, Pfeffer und nach Wunsch einem Spritzer Zitrone würzen. Auf den Toast streichen."], ["Rührei zubereiten", "Eier verquirlen und leicht salzen. In eine beschichtete Pfanne bei niedriger bis mittlerer Hitze geben und mit einem Pfannenwender langsam zur Mitte schieben, bis cremige Flocken entstehen. Nach ca. 2–3 Minuten vom Herd nehmen, solange es noch leicht feucht ist."], ["Anrichten", "Rührei auf dem Avocado-Toast verteilen, mit Chiliflocken bestreuen. Kirschtomaten halbieren und dazu servieren."]]},
{"id": "chia-pudding-mit-mango", "cat": "fruehstueck", "ty": "veggie", "kcal": 220, "t": "5 Min. + 2 Std.", "name": "Chia-Pudding mit Mango", "g": [["Zutaten", [[2, "EL", "Chiasamen"], [200, "ml", "Pflanzenmilch (ungesüßt)"], [50, "g", "Mango oder Beeren"]]]], "s": [["Anrühren", "Chiasamen und Pflanzenmilch in einem Glas gründlich verrühren."], ["Nachrühren", "Nach 10 Minuten noch einmal kräftig umrühren. So bilden sich keine Klümpchen am Boden."], ["Quellen lassen", "Abgedeckt mindestens 2 Stunden oder über Nacht in den Kühlschrank stellen, bis eine puddingartige Konsistenz entsteht."], ["Obst vorbereiten", "Mango schälen, vom Kern schneiden und würfeln oder Beeren waschen."], ["Servieren", "Pudding umrühren (bei Bedarf 1–2 EL Milch zugeben) und mit dem Obst toppen."]]},
{"id": "haehnchen-gemuese-pfanne", "cat": "mittag", "ty": "haehnchen", "kcal": 400, "t": "20 Min.", "name": "Hähnchen-Gemüse-Pfanne", "g": [["Zutaten", [[150, "g", "Hähnchenbrust"], [1, "", "Zucchini"], [1, "", "Paprika"], [100, "g", "Brokkoli"], [1, "TL", "Öl"], [1, "EL", "Sojasauce"], [null, "", "Knoblauch, Ingwer"]]]], "s": [["Vorbereiten", "Hähnchenbrust trocken tupfen und in dünne Streifen schneiden. Zucchini halbieren und in Scheiben schneiden, Paprika in Streifen, Brokkoli in kleine Röschen teilen. Knoblauch und Ingwer fein hacken."], ["Hähnchen anbraten", "Öl in einer großen Pfanne oder einem Wok stark erhitzen. Hähnchen 3–4 Minuten rundherum goldbraun braten, bis es durchgegart ist. Herausnehmen."], ["Gemüse braten", "Brokkoli in die Pfanne geben, 2 EL Wasser zugeben und 2 Minuten zugedeckt dämpfen. Zucchini, Paprika, Knoblauch und Ingwer zufügen und 4–5 Minuten unter Rühren bissfest braten."], ["Abschmecken", "Hähnchen zurück in die Pfanne geben, mit Sojasauce ablöschen, alles gut durchschwenken und mit Pfeffer abschmecken."]]},
{"id": "linsensuppe", "cat": "mittag", "ty": "veggie", "kcal": 350, "t": "30 Min.", "name": "Linsensuppe", "g": [["Zutaten", [[60, "g", "rote Linsen"], [1, "", "Karotte"], [0.5, "", "Zwiebel"], [200, "g", "gehackte Tomaten"], [300, "ml", "Gemüsebrühe"], [null, "", "Kreuzkümmel, Paprikapulver"]]]], "s": [["Gemüse schneiden", "Zwiebel und Karotte schälen und klein würfeln."], ["Andünsten", "In einem Topf mit einem Schuss Brühe (oder etwas Öl) 3 Minuten andünsten. Kreuzkümmel und Paprikapulver zugeben und kurz mitrösten."], ["Linsen zugeben", "Linsen in einem Sieb abspülen und mit Tomaten und Gemüsebrühe in den Topf geben. Aufkochen lassen."], ["Köcheln", "Bei mittlerer Hitze 15–20 Minuten köcheln lassen, bis die Linsen weich sind und zerfallen. Gelegentlich umrühren."], ["Fertigstellen", "Nach Wunsch mit dem Stabmixer ganz oder teilweise pürieren. Mit Salz, Pfeffer und einem Spritzer Zitronensaft abschmecken."]]},
{"id": "quinoa-salat-mit-feta", "cat": "mittag", "ty": "veggie", "kcal": 420, "t": "20 Min.", "name": "Quinoa-Salat mit Feta", "g": [["Zutaten", [[50, "g", "Quinoa"], [0.5, "", "Gurke"], [8, "", "Kirschtomaten"], [30, "g", "Feta"], [1, "TL", "Olivenöl"], [null, "", "Zitronensaft, Petersilie"]]]], "s": [["Quinoa waschen", "Quinoa in einem feinen Sieb gründlich unter kaltem Wasser abspülen, um Bitterstoffe zu entfernen."], ["Kochen", "Mit der doppelten Menge Wasser und einer Prise Salz aufkochen, dann zugedeckt bei niedriger Hitze 12–15 Minuten garen, bis das Wasser aufgesogen ist. Abkühlen lassen."], ["Gemüse schneiden", "Gurke würfeln, Kirschtomaten halbieren, Petersilie fein hacken."], ["Dressing", "Olivenöl mit Zitronensaft, Salz und Pfeffer verrühren."], ["Mischen", "Quinoa, Gemüse und Petersilie mit dem Dressing vermengen und den Feta darüberbröseln. Schmeckt auch am nächsten Tag noch."]]},
{"id": "lachs-mit-ofengemuese", "cat": "mittag", "ty": "fisch", "kcal": 450, "t": "30 Min.", "name": "Lachs mit Ofengemüse", "g": [["Zutaten", [[120, "g", "Lachsfilet"], [150, "g", "grüne Bohnen oder Spargel"], [100, "g", "Kirschtomaten"], [1, "TL", "Olivenöl"], [null, "", "Zitrone, Dill, Salz, Pfeffer"]]]], "s": [["Ofen vorheizen", "Backofen auf 200 °C Ober-/Unterhitze vorheizen. Ein Blech mit Backpapier auslegen."], ["Gemüse vorbereiten", "Grüne Bohnen putzen (bzw. Spargel schälen und holzige Enden abschneiden). Mit Kirschtomaten, Olivenöl, Salz und Pfeffer mischen und auf dem Blech verteilen."], ["Vorgaren", "Gemüse 8 Minuten im Ofen vorgaren."], ["Lachs dazulegen", "Lachs trocken tupfen, salzen, pfeffern und auf das Gemüse legen. Mit Zitronenscheiben und Dill belegen."], ["Fertig backen", "Alles weitere 12–15 Minuten backen, bis der Lachs sich leicht mit der Gabel zerteilen lässt und innen noch saftig ist."]]},
{"id": "zucchini-nudeln-mit-tomatensauce", "cat": "mittag", "ty": "veggie", "kcal": 300, "t": "15 Min.", "name": "Zucchini-Nudeln mit Tomatensauce", "g": [["Zutaten", [[2, "", "Zucchini"], [200, "g", "passierte Tomaten"], [1, "", "Knoblauchzehe"], [100, "g", "Hüttenkäse (oder 20 g Parmesan)"], [null, "", "Basilikum, Oregano"]]]], "s": [["Sauce ansetzen", "Knoblauch fein hacken und mit den passierten Tomaten, Oregano, Salz und Pfeffer in einem kleinen Topf aufkochen. Bei niedriger Hitze 8–10 Minuten köcheln lassen."], ["Zucchini-Nudeln schneiden", "Zucchini waschen, Enden abschneiden und mit einem Spiralschneider zu Nudeln drehen. Wer keinen hat, nimmt einen Sparschäler für breite Bandnudeln."], ["Kurz braten", "Zucchini-Nudeln in einer beschichteten Pfanne ohne Fett 2 Minuten bei hoher Hitze schwenken. Nicht länger, sonst werden sie weich und wässrig."], ["Anrichten", "Nudeln auf einen Teller geben, Sauce darüber verteilen, Hüttenkäse oder Parmesan darauf und mit frischem Basilikum bestreuen."]]},
{"id": "kichererbsen-bowl", "cat": "mittag", "ty": "veggie", "kcal": 420, "t": "15 Min.", "name": "Kichererbsen-Bowl", "g": [["Zutaten", [[120, "g", "Kichererbsen (Dose)"], [1, "Handvoll", "Blattsalat"], [0.5, "", "Paprika"], [0.25, "", "Gurke"], [2, "EL", "Hummus"], [null, "", "Paprikapulver, Zitronensaft"]]]], "s": [["Kichererbsen vorbereiten", "Kichererbsen in ein Sieb geben, gründlich abspülen und mit Küchenpapier trocken tupfen."], ["Rösten", "In einer beschichteten Pfanne bei mittlerer bis hoher Hitze 5–6 Minuten rösten, bis sie leicht knusprig sind. Mit Paprikapulver und Salz würzen."], ["Gemüse schneiden", "Salat waschen und trocken schleudern. Paprika in Streifen, Gurke in Scheiben schneiden."], ["Anrichten", "Salat und Gemüse in eine Schüssel geben, Kichererbsen darauf verteilen und den Hummus in die Mitte setzen."], ["Würzen", "Mit Zitronensaft beträufeln und mit Pfeffer abschmecken. Der Hummus dient gleichzeitig als Dressing."]]},
{"id": "putenwrap-mit-salat", "cat": "mittag", "ty": "pute", "kcal": 380, "t": "10 Min.", "name": "Putenwrap mit Salat", "g": [["Zutaten", [[1, "", "Vollkorn-Tortilla"], [80, "g", "Putenbrust (gebraten oder Aufschnitt)"], [null, "", "Salatblätter, Tomate, Gurke"], [2, "EL", "Joghurt-Kräuter-Dip"]]]], "s": [["Pute vorbereiten", "Falls frische Putenbrust: in einer beschichteten Pfanne 3–4 Minuten pro Seite braten, salzen, pfeffern und in Streifen schneiden. Aufschnitt einfach in Streifen schneiden."], ["Gemüse schneiden", "Salat waschen und trocknen, Tomate und Gurke in dünne Scheiben schneiden."], ["Tortilla erwärmen", "Tortilla in einer Pfanne ohne Fett ca. 20 Sekunden pro Seite erwärmen. So reißt sie beim Rollen nicht."], ["Belegen", "Tortilla mit dem Dip bestreichen, dabei rundherum 2 cm Rand lassen. Salat, Gemüse und Pute im unteren Drittel verteilen."], ["Rollen", "Seiten einschlagen, dann von unten fest aufrollen. Schräg halbieren. Zum Mitnehmen in Backpapier oder Alufolie wickeln."]]},
{"id": "gemuesesticks-mit-kraeuterquark", "cat": "snack", "ty": "veggie", "kcal": 130, "t": "10 Min.", "name": "Gemüsesticks mit Kräuterquark", "g": [["Zutaten", [[1, "", "Karotte"], [0.5, "", "Gurke"], [0.5, "", "Paprika"], [100, "g", "Magerquark"], [1, "EL", "Mineralwasser"], [null, "", "Kräuter, Salz, Pfeffer"]]]], "s": [["Gemüse schneiden", "Karotte schälen, Gurke und Paprika waschen. Alles in fingerdicke Sticks schneiden."], ["Quark anrühren", "Magerquark mit dem Mineralwasser cremig rühren. Durch die Kohlensäure wird er schön luftig."], ["Würzen", "Kräuter fein hacken und unterheben, mit Salz und Pfeffer abschmecken."], ["Servieren", "Quark in ein Schälchen füllen und die Gemüsesticks dazu stellen. Zum Mitnehmen alles in eine Dose mit Deckel geben."]]},
{"id": "apfelspalten-mit-erdnussmus", "cat": "snack", "ty": "veggie", "kcal": 180, "t": "3 Min.", "name": "Apfelspalten mit Erdnussmus", "g": [["Zutaten", [[1, "", "Apfel"], [1, "EL", "Erdnussmus (ohne Zucker)"]]]], "s": [["Apfel schneiden", "Apfel waschen, vierteln, das Kerngehäuse entfernen und in Spalten schneiden."], ["Braun werden verhindern", "Wer die Spalten mitnehmen möchte, beträufelt sie mit etwas Zitronensaft."], ["Dip vorbereiten", "Erdnussmus in ein kleines Schälchen geben und glatt rühren. Ist es zu fest, kurz mit 1 TL warmem Wasser verrühren."], ["Genießen", "Apfelspalten in das Erdnussmus dippen. Wer mag, bestreut alles mit einer Prise Zimt."]]},
{"id": "knusprige-ofen-kichererbsen", "cat": "snack", "ty": "veggie", "kcal": 140, "t": "30 Min.", "name": "Knusprige Ofen-Kichererbsen", "g": [["Zutaten", [[100, "g", "Kichererbsen (Dose, abgetropft)"], [0.5, "TL", "Olivenöl"], [0.5, "TL", "Paprikapulver"], [null, "", "Salz"]]]], "s": [["Ofen vorheizen", "Backofen auf 200 °C Umluft vorheizen und ein Blech mit Backpapier auslegen."], ["Trocknen", "Kichererbsen abspülen und sehr gründlich mit Küchenpapier trocken tupfen. Lose Häutchen entfernen. Je trockener, desto knuspriger."], ["Würzen", "Mit Olivenöl, Paprikapulver und Salz in einer Schüssel mischen."], ["Rösten", "In einer Lage auf dem Blech verteilen und ca. 25 Minuten rösten. Nach der Hälfte der Zeit einmal durchschütteln."], ["Abkühlen lassen", "Auf dem Blech abkühlen lassen, dabei werden sie noch knuspriger. Am selben Tag essen."]]},
{"id": "edamame-mit-meersalz", "cat": "snack", "ty": "veggie", "kcal": 125, "t": "6 Min.", "name": "Edamame mit Meersalz", "g": [["Zutaten", [[100, "g", "Edamame (TK, geschält)"], [null, "", "Meersalz, etwas Chili"]]]], "s": [["Wasser aufkochen", "Reichlich Wasser in einem Topf mit 1 TL Salz zum Kochen bringen."], ["Kochen", "Gefrorene Edamame hineingeben und 4–5 Minuten kochen lassen."], ["Abgießen", "In ein Sieb abgießen und kurz abtropfen lassen."], ["Würzen", "Noch warm in eine Schale geben, mit grobem Meersalz und nach Wunsch etwas Chili bestreuen und durchschwenken."]]},
{"id": "joghurt-mit-beeren-und-mandeln", "cat": "snack", "ty": "veggie", "kcal": 170, "t": "3 Min.", "name": "Joghurt mit Beeren und Mandeln", "g": [["Zutaten", [[150, "g", "Naturjoghurt (1,5 %)"], [80, "g", "Beeren"], [10, "g", "Mandeln (gehackt)"]]]], "s": [["Mandeln rösten", "Gehackte Mandeln in einer Pfanne ohne Fett bei mittlerer Hitze 2 Minuten goldbraun rösten. Dabei ständig rühren, sie verbrennen schnell."], ["Beeren vorbereiten", "Beeren waschen und abtropfen lassen. Große Erdbeeren halbieren."], ["Anrichten", "Joghurt in eine Schale geben, Beeren darauf verteilen und mit den Mandeln bestreuen."]]},
{"id": "reiswaffeln-mit-huettenkaese-und-tomate", "cat": "snack", "ty": "veggie", "kcal": 130, "t": "3 Min.", "name": "Reiswaffeln mit Hüttenkäse und Tomate", "g": [["Zutaten", [[2, "", "Reiswaffeln"], [60, "g", "Hüttenkäse"], [1, "", "kleine Tomate"], [null, "", "Pfeffer, Schnittlauch"]]]], "s": [["Tomate schneiden", "Tomate waschen und in dünne Scheiben schneiden."], ["Bestreichen", "Hüttenkäse gleichmäßig auf die Reiswaffeln verteilen. Erst kurz vor dem Essen bestreichen, damit sie knusprig bleiben."], ["Belegen", "Tomatenscheiben darauflegen."], ["Würzen", "Mit Pfeffer und Schnittlauchröllchen bestreuen. Eine Prise Salz rundet es ab."]]},
{"id": "gekochte-eier-mit-kirschtomaten", "cat": "snack", "ty": "veggie", "kcal": 170, "t": "10 Min.", "name": "Gekochte Eier mit Kirschtomaten", "g": [["Zutaten", [[2, "", "Eier"], [5, "", "Kirschtomaten"], [null, "", "Salz, Pfeffer"]]]], "s": [["Wasser aufkochen", "In einem kleinen Topf so viel Wasser zum Kochen bringen, dass die Eier bedeckt sind."], ["Eier kochen", "Eier am stumpfen Ende anstechen und mit einem Löffel vorsichtig ins kochende Wasser legen. 8–9 Minuten kochen lassen."], ["Abschrecken", "Eier herausnehmen und sofort in kaltes Wasser legen. So lassen sie sich leichter schälen."], ["Servieren", "Schälen, halbieren, mit Salz und Pfeffer würzen und mit den Kirschtomaten servieren. Ungeschält halten sich die Eier im Kühlschrank bis zu 5 Tage."]]},
{"id": "herzhafter-kraeuterquark-mit-knaeckebrot", "cat": "fruehstueck", "ty": "veggie", "kcal": 200, "t": "5 Min.", "name": "Herzhafter Kräuterquark mit Knäckebrot", "g": [["Zutaten", [[150, "g", "Magerquark"], [1, "", "Tomate"], [0.25, "", "Gurke"], [2, "Scheiben", "Vollkorn-Knäckebrot"], [null, "", "Schnittlauch, Salz, Pfeffer"]]]], "s": [["Quark anrühren", "Magerquark mit 1–2 EL Wasser oder Mineralwasser cremig rühren."], ["Würzen", "Schnittlauch in feine Röllchen schneiden und unterheben. Mit Salz und Pfeffer abschmecken. Nach Wunsch etwas Knoblauch oder Paprikapulver dazugeben."], ["Gemüse schneiden", "Tomate und Gurke waschen und in Scheiben oder Stifte schneiden."], ["Servieren", "Quark auf die Knäckebrote streichen oder separat als Dip servieren und mit dem Gemüse belegen."]]},
{"id": "porridge-mit-apfel-und-zimt", "cat": "fruehstueck", "ty": "veggie", "kcal": 290, "t": "10 Min.", "name": "Porridge mit Apfel und Zimt", "g": [["Zutaten", [[40, "g", "Haferflocken"], [200, "ml", "Milch (1,5 %)"], [0.5, "", "Apfel"], [0.5, "TL", "Zimt"]]]], "s": [["Aufkochen", "Haferflocken und Milch in einem kleinen Topf mit einer Prise Salz verrühren und unter Rühren aufkochen."], ["Köcheln", "Hitze reduzieren und das Porridge 3–4 Minuten unter häufigem Rühren köcheln lassen, bis es cremig ist. Bei Bedarf einen Schluck Milch nachgießen."], ["Apfel vorbereiten", "Währenddessen den Apfel waschen, entkernen und würfeln. Wer mag, dünstet die Würfel 2 Minuten mit einem Schluck Wasser und Zimt in einer Pfanne an."], ["Servieren", "Porridge in eine Schale füllen, Apfel darauf verteilen und mit Zimt bestäuben."]]},
{"id": "bircher-muesli", "cat": "fruehstueck", "ty": "veggie", "kcal": 260, "t": "5 Min. + 1 Std.", "name": "Bircher-Müsli", "g": [["Zutaten", [[30, "g", "Haferflocken"], [100, "g", "Naturjoghurt (1,5 %)"], [50, "ml", "Milch (1,5 %)"], [0.5, "", "Apfel"], [1, "TL", "Zitronensaft"], [5, "g", "Haselnüsse (gehackt)"]]]], "s": [["Einweichen", "Haferflocken mit Joghurt und Milch in einer Schüssel verrühren."], ["Quellen lassen", "Abgedeckt mindestens 1 Stunde, am besten über Nacht, in den Kühlschrank stellen."], ["Apfel reiben", "Kurz vor dem Servieren den Apfel waschen und mit Schale grob reiben. Sofort mit dem Zitronensaft mischen, damit er nicht braun wird."], ["Fertigstellen", "Geriebenen Apfel unter das Müsli heben. Haselnüsse in einer Pfanne ohne Fett kurz anrösten und darüberstreuen."]]},
{"id": "protein-pfannkuchen-mit-beeren", "cat": "fruehstueck", "ty": "veggie", "kcal": 240, "t": "15 Min.", "name": "Protein-Pfannkuchen mit Beeren", "g": [["Zutaten", [[1, "", "Ei"], [50, "g", "Magerquark"], [20, "g", "zarte Haferflocken"], [80, "g", "Beeren"], [0.5, "TL", "Rapsöl"]]]], "s": [["Teig anrühren", "Ei, Magerquark und Haferflocken in einer Schüssel glatt verrühren. Nach Wunsch eine Prise Zimt oder etwas Vanille zugeben."], ["Quellen lassen", "Teig 5 Minuten ruhen lassen, damit die Haferflocken etwas Flüssigkeit aufnehmen."], ["Pfanne vorbereiten", "Eine beschichtete Pfanne bei mittlerer Hitze erwärmen und mit dem Öl dünn auspinseln."], ["Ausbacken", "Je 1–2 EL Teig pro Pfannkuchen in die Pfanne geben und 2–3 Minuten backen, bis die Unterseite goldbraun ist und sich Bläschen zeigen. Wenden und weitere 1–2 Minuten backen."], ["Servieren", "Beeren waschen und zu den Pfannkuchen servieren. Ein Klecks Joghurt passt gut dazu."]]},
{"id": "shakshuka-fuer-eine-person", "cat": "fruehstueck", "ty": "veggie", "kcal": 260, "t": "20 Min.", "name": "Shakshuka für eine Person", "g": [["Zutaten", [[2, "", "Eier"], [200, "g", "gehackte Tomaten (Dose)"], [0.5, "", "Paprika"], [0.25, "", "Zwiebel"], [1, "TL", "Olivenöl"], [null, "", "Kreuzkümmel, Paprikapulver, Salz, Petersilie"]]]], "s": [["Gemüse andünsten", "Zwiebel und Paprika fein würfeln. Öl in einer kleinen Pfanne (ca. 20 cm) erhitzen und das Gemüse bei mittlerer Hitze 3 Minuten glasig dünsten."], ["Gewürze rösten", "Kreuzkümmel und Paprikapulver zugeben und 30 Sekunden mitrösten, bis es duftet."], ["Sauce köcheln", "Gehackte Tomaten zugeben, salzen und 5 Minuten offen köcheln lassen, bis die Sauce etwas eindickt."], ["Eier garen", "Mit einem Löffel zwei Mulden in die Sauce drücken und je ein Ei hineinschlagen. Deckel auflegen und bei niedriger Hitze 6–8 Minuten stocken lassen, bis das Eiweiß fest und das Eigelb noch weich ist."], ["Servieren", "Mit Pfeffer und gehackter Petersilie bestreuen und direkt aus der Pfanne essen."]]},
{"id": "joghurt-bowl-mit-kiwi-und-leinsamen", "cat": "fruehstueck", "ty": "veggie", "kcal": 220, "t": "5 Min.", "name": "Joghurt-Bowl mit Kiwi und Leinsamen", "g": [["Zutaten", [[150, "g", "Naturjoghurt (1,5 %)"], [1, "", "Kiwi"], [1, "EL", "geschrotete Leinsamen"], [15, "g", "zarte Haferflocken"]]]], "s": [["Haferflocken rösten", "Haferflocken in einer Pfanne ohne Fett bei mittlerer Hitze 2 Minuten goldbraun rösten. Das gibt ein nussiges Aroma."], ["Kiwi vorbereiten", "Kiwi schälen und in Scheiben oder Würfel schneiden."], ["Anrichten", "Joghurt in eine Schale geben, glatt streichen und Kiwi, Haferflocken und Leinsamen darauf verteilen."], ["Tipp", "Geschrotete Leinsamen kann der Körper besser verwerten als ganze. Am besten luftdicht im Kühlschrank lagern."]]},
{"id": "vollkornbrot-mit-raeucherlachs-und-gurke", "cat": "fruehstueck", "ty": "fisch", "kcal": 220, "t": "5 Min.", "name": "Vollkornbrot mit Räucherlachs und Gurke", "g": [["Zutaten", [[1, "Scheibe", "Vollkornbrot (ca. 50 g)"], [20, "g", "Frischkäse light"], [40, "g", "Räucherlachs"], [0.25, "", "Gurke"], [null, "", "Dill, Pfeffer"]]]], "s": [["Gurke vorbereiten", "Gurke waschen und in dünne Scheiben schneiden oder hobeln."], ["Bestreichen", "Vollkornbrot nach Wunsch kurz toasten und mit dem Frischkäse bestreichen."], ["Belegen", "Gurkenscheiben auf den Frischkäse legen, Räucherlachs locker darauf verteilen."], ["Würzen", "Mit frischem Dill und Pfeffer bestreuen. Ein Spritzer Zitrone rundet es ab."]]},
{"id": "caprese-mit-rucola-und-vollkornbrot", "cat": "mittag", "ty": "veggie", "kcal": 410, "t": "10 Min.", "name": "Caprese mit Rucola und Vollkornbrot", "g": [["Zutaten", [[125, "g", "Mozzarella light"], [2, "", "Tomaten"], [1, "Handvoll", "Rucola"], [1, "TL", "Olivenöl"], [1, "TL", "Balsamico"], [1, "Scheibe", "Vollkornbrot"], [null, "", "Basilikum, Salz, Pfeffer"]]]], "s": [["Vorbereiten", "Rucola waschen und trocken schleudern. Tomaten und Mozzarella in etwa 0,5 cm dicke Scheiben schneiden. Mozzarella gut abtropfen lassen."], ["Anrichten", "Rucola auf einem Teller verteilen. Tomaten- und Mozzarellascheiben abwechselnd daraufschichten."], ["Würzen", "Mit Salz und Pfeffer würzen, mit Olivenöl und Balsamico beträufeln und mit frischen Basilikumblättern belegen."], ["Brot dazu", "Vollkornbrot kurz toasten und dazu servieren."]]},
{"id": "thunfisch-bohnen-salat", "cat": "mittag", "ty": "fisch", "kcal": 270, "t": "10 Min.", "name": "Thunfisch-Bohnen-Salat", "g": [["Zutaten", [[80, "g", "Thunfisch im eigenen Saft (abgetropft)"], [100, "g", "weiße Bohnen (Dose, abgetropft)"], [0.5, "", "rote Zwiebel"], [6, "", "Kirschtomaten"], [1, "TL", "Olivenöl"], [null, "", "Zitronensaft, Petersilie, Salz, Pfeffer"]]]], "s": [["Abtropfen", "Weiße Bohnen in einem Sieb abspülen und gut abtropfen lassen. Thunfisch abtropfen lassen."], ["Schneiden", "Rote Zwiebel in feine Ringe oder Würfel schneiden, Kirschtomaten halbieren, Petersilie hacken."], ["Dressing", "Olivenöl mit Zitronensaft, Salz und Pfeffer verrühren."], ["Mischen", "Bohnen, Zwiebel und Tomaten mit dem Dressing mischen. Thunfisch grob zerpflücken und vorsichtig unterheben, mit Petersilie bestreuen."], ["Ziehen lassen", "Den Salat 5–10 Minuten ziehen lassen, dann schmeckt er intensiver. Gut zum Mitnehmen."]]},
{"id": "puten-gemuese-reispfanne", "cat": "mittag", "ty": "pute", "kcal": 370, "t": "25 Min.", "name": "Puten-Gemüse-Reispfanne", "g": [["Zutaten", [[100, "g", "Putenbrust"], [40, "g", "Vollkornreis (roh)"], [0.5, "", "Zucchini"], [0.5, "", "Paprika"], [50, "g", "Erbsen (TK)"], [1, "TL", "Öl"], [1, "EL", "Sojasauce"]]]], "s": [["Reis kochen", "Vollkornreis nach Packungsanweisung in Salzwasser garen (meist ca. 25 Minuten). Abgießen. Tipp: Reis vom Vortag funktioniert besonders gut."], ["Vorbereiten", "Putenbrust in Streifen schneiden. Zucchini und Paprika würfeln."], ["Fleisch braten", "Öl in einer großen Pfanne erhitzen und die Pute 3–4 Minuten rundherum anbraten, bis sie durch ist. Herausnehmen."], ["Gemüse braten", "Zucchini und Paprika 3 Minuten braten, Erbsen zugeben und weitere 2 Minuten mitbraten."], ["Fertigstellen", "Reis und Pute zugeben, alles gut vermengen, mit Sojasauce und Pfeffer abschmecken und 1–2 Minuten durchbraten."]]},
{"id": "ofen-suesskartoffel-mit-kraeuterquark", "cat": "mittag", "ty": "veggie", "kcal": 310, "t": "45 Min.", "name": "Ofen-Süßkartoffel mit Kräuterquark", "g": [["Zutaten", [[1, "", "Süßkartoffel (ca. 250 g)"], [0.5, "TL", "Olivenöl"], [100, "g", "Magerquark"], [null, "", "Kräuter, Paprikapulver, Salz, Pfeffer"]]]], "s": [["Ofen vorheizen", "Backofen auf 200 °C Ober-/Unterhitze vorheizen."], ["Vorbereiten", "Süßkartoffel gründlich waschen und trocken tupfen. Längs halbieren, die Schnittflächen mit Olivenöl bepinseln und leicht salzen."], ["Backen", "Mit der Schnittfläche nach unten auf ein Blech mit Backpapier legen und 35–40 Minuten backen, bis sie sich mit einer Gabel leicht einstechen lässt."], ["Quark anrühren", "Währenddessen Magerquark mit 1–2 EL Wasser glatt rühren, gehackte Kräuter unterheben und mit Salz und Pfeffer würzen."], ["Servieren", "Süßkartoffelhälften umdrehen, das Fruchtfleisch mit einer Gabel etwas auflockern, Quark daraufgeben und mit Paprikapulver bestreuen."]]},
{"id": "glasnudelsalat-mit-garnelen", "cat": "mittag", "ty": "fisch", "kcal": 290, "t": "15 Min.", "name": "Glasnudelsalat mit Garnelen", "g": [["Zutaten", [[40, "g", "Glasnudeln"], [80, "g", "Garnelen (gegart)"], [0.5, "", "Paprika"], [0.25, "", "Gurke"], [1, "", "kleine Karotte"], [1, "EL", "Sojasauce"], [1, "TL", "Sesamöl"], [null, "", "Limettensaft, Koriander"]]]], "s": [["Nudeln einweichen", "Glasnudeln in eine Schüssel geben, mit kochendem Wasser übergießen und 5 Minuten ziehen lassen. Abgießen, kalt abspülen und mit einer Schere etwas kürzer schneiden."], ["Gemüse schneiden", "Paprika, Gurke und Karotte in sehr feine Streifen schneiden oder hobeln."], ["Dressing", "Sojasauce, Sesamöl und Limettensaft verrühren. Nach Wunsch etwas Chili zugeben."], ["Mischen", "Glasnudeln, Gemüse und Garnelen mit dem Dressing vermengen und 5 Minuten durchziehen lassen."], ["Servieren", "Mit gehacktem Koriander bestreuen. Schmeckt kalt am besten."]]},
{"id": "kuerbissuppe-mit-ingwer", "cat": "mittag", "ty": "veggie", "kcal": 330, "t": "30 Min.", "name": "Kürbissuppe mit Ingwer", "g": [["Zutaten", [[300, "g", "Hokkaido-Kürbis"], [1, "", "Karotte"], [0.5, "", "Zwiebel"], [1, "Stück", "Ingwer (2 cm)"], [300, "ml", "Gemüsebrühe"], [2, "EL", "Kokosmilch light"], [1, "TL", "Kürbiskerne"], [1, "Scheibe", "Vollkornbrot (dazu)"]]]], "s": [["Gemüse schneiden", "Kürbis waschen, halbieren und die Kerne mit einem Löffel herauskratzen. Hokkaido muss nicht geschält werden. In Würfel schneiden. Karotte und Zwiebel schälen und würfeln, Ingwer schälen und reiben."], ["Andünsten", "Zwiebel und Ingwer mit einem Schuss Brühe in einem Topf 2 Minuten andünsten."], ["Kochen", "Kürbis, Karotte und restliche Brühe zugeben, aufkochen und zugedeckt ca. 20 Minuten köcheln lassen, bis alles weich ist."], ["Pürieren", "Mit dem Stabmixer fein pürieren. Ist die Suppe zu dick, etwas Wasser zugeben. Mit Salz und Pfeffer abschmecken."], ["Servieren", "Kokosmilch einrühren oder als Spirale daraufgeben. Kürbiskerne in einer Pfanne ohne Fett kurz rösten und darüberstreuen. Brot dazu reichen."]]},
{"id": "caesar-salad-light-mit-haehnchen", "cat": "mittag", "ty": "haehnchen", "kcal": 320, "t": "20 Min.", "name": "Caesar Salad light mit Hähnchen", "g": [["Zutaten", [[120, "g", "Hähnchenbrust"], [1, "", "kleiner Romanasalat"], [6, "", "Kirschtomaten"], [2, "EL", "Naturjoghurt (1,5 %)"], [1, "TL", "Senf"], [10, "g", "Parmesan (gerieben)"], [1, "Scheibe", "Vollkorntoast"], [null, "", "Zitronensaft, Salz, Pfeffer"]]]], "s": [["Hähnchen braten", "Hähnchenbrust trocken tupfen, salzen und pfeffern. In einer beschichteten Pfanne ohne Fett bei mittlerer Hitze 5–6 Minuten pro Seite braten, bis sie durchgegart ist. 3 Minuten ruhen lassen, dann in Streifen schneiden."], ["Croutons rösten", "Toast in kleine Würfel schneiden und in derselben Pfanne 3–4 Minuten unter Wenden knusprig rösten."], ["Dressing", "Joghurt, Senf, Zitronensaft, die Hälfte des Parmesans, Salz und Pfeffer glatt rühren. Bei Bedarf mit etwas Wasser verdünnen."], ["Salat vorbereiten", "Romanasalat waschen, trocken schleudern und in mundgerechte Stücke zupfen. Kirschtomaten halbieren."], ["Anrichten", "Salat und Tomaten mit dem Dressing mischen, Hähnchen und Croutons darauf verteilen und mit dem restlichen Parmesan bestreuen."]]},
{"id": "huettenkaese-mit-ananas", "cat": "snack", "ty": "veggie", "kcal": 150, "t": "2 Min.", "name": "Hüttenkäse mit Ananas", "g": [["Zutaten", [[100, "g", "Hüttenkäse"], [80, "g", "Ananas"]]]], "s": [["Ananas vorbereiten", "Frische Ananas schälen, den harten Strunk entfernen und das Fruchtfleisch in kleine Würfel schneiden. Alternativ Ananas aus der Dose im eigenen Saft verwenden und gut abtropfen lassen."], ["Anrichten", "Hüttenkäse in eine Schale geben und die Ananaswürfel darauf verteilen."], ["Tipp", "Mit etwas Zimt oder frischer Minze bekommt der Snack einen besonderen Kick."]]},
{"id": "paprikastreifen-mit-hummus", "cat": "snack", "ty": "veggie", "kcal": 140, "t": "3 Min.", "name": "Paprikastreifen mit Hummus", "g": [["Zutaten", [[1, "", "Paprika"], [40, "g", "Hummus"]]]], "s": [["Paprika schneiden", "Paprika waschen, halbieren, Kerne und weiße Häute entfernen und in breite Streifen schneiden."], ["Hummus anrichten", "Hummus in ein Schälchen geben. Nach Wunsch mit etwas Paprikapulver oder Kreuzkümmel bestreuen."], ["Servieren", "Paprikastreifen zum Dippen dazu servieren. Bunte Paprika sehen besonders schön aus."]]},
{"id": "gefrorene-joghurt-beeren", "cat": "snack", "ty": "veggie", "kcal": 110, "t": "5 Min. + 2 Std.", "name": "Gefrorene Joghurt-Beeren", "g": [["Zutaten", [[100, "g", "Naturjoghurt (1,5 %)"], [100, "g", "Heidelbeeren oder Himbeeren"], [1, "TL", "Honig"]]]], "s": [["Vorbereiten", "Ein Brett oder einen flachen Teller mit Backpapier belegen, der ins Gefrierfach passt. Beeren waschen und sehr gut trocken tupfen."], ["Joghurt anrühren", "Joghurt mit dem Honig glatt verrühren."], ["Eintauchen", "Beeren einzeln mit einer Gabel oder einem Zahnstocher in den Joghurt tauchen, abtropfen lassen und mit Abstand auf das Backpapier setzen."], ["Gefrieren", "Mindestens 2 Stunden gefrieren lassen."], ["Aufbewahren", "Gefrorene Beeren in eine Gefrierdose umfüllen. Sie halten sich bis zu 4 Wochen. Direkt aus dem Gefrierfach genießen."]]},
{"id": "mandarine-mit-walnuessen", "cat": "snack", "ty": "veggie", "kcal": 135, "t": "1 Min.", "name": "Mandarine mit Walnüssen", "g": [["Zutaten", [[1, "", "Mandarine"], [15, "g", "Walnüsse"]]]], "s": [["Walnüsse rösten", "Walnüsse nach Wunsch in einer Pfanne ohne Fett 2–3 Minuten anrösten, bis sie duften. Kurz abkühlen lassen."], ["Mandarine schälen", "Mandarine schälen und in Spalten teilen."], ["Genießen", "Zusammen genießen. Die Kombination aus Fruchtsäure und Nüssen sättigt gut und liefert gesunde Fette."]]},
{"id": "gurkenroellchen-mit-lachs", "cat": "snack", "ty": "fisch", "kcal": 110, "t": "10 Min.", "name": "Gurkenröllchen mit Lachs", "g": [["Zutaten", [[0.5, "", "Gurke"], [30, "g", "Frischkäse light"], [30, "g", "Räucherlachs"], [null, "", "Dill"]]]], "s": [["Gurke schneiden", "Gurke waschen und mit einem Sparschäler der Länge nach in dünne, breite Streifen schneiden. Die ersten Streifen mit viel Schale weglassen. Streifen kurz auf Küchenpapier abtropfen lassen."], ["Bestreichen", "Jeden Gurkenstreifen dünn mit Frischkäse bestreichen."], ["Belegen", "Ein Stück Räucherlachs und etwas Dill darauflegen."], ["Aufrollen", "Streifen aufrollen und mit einem Zahnstocher fixieren. Mit Pfeffer bestreuen und gekühlt servieren."]]},
{"id": "selbstgemachtes-popcorn", "cat": "snack", "ty": "veggie", "kcal": 120, "t": "5 Min.", "name": "Selbstgemachtes Popcorn", "g": [["Zutaten", [[20, "g", "Popcornmais"], [1, "TL", "Rapsöl"], [null, "", "Salz oder Zimt"]]]], "s": [["Topf vorbereiten", "Rapsöl in einen großen Topf mit Deckel geben und 3 Maiskörner dazulegen. Bei mittlerer bis hoher Hitze erwärmen."], ["Mais zugeben", "Sobald die Probe-Körner aufpoppen, den restlichen Mais zugeben, Deckel auflegen und den Topf kurz schwenken, damit alle Körner mit Öl benetzt sind."], ["Poppen lassen", "Bei mittlerer Hitze poppen lassen und den Topf dabei immer wieder leicht rütteln. Wenn zwischen dem Knallen 2–3 Sekunden Pause sind, vom Herd nehmen."], ["Würzen", "Popcorn in eine Schüssel geben und sofort mit etwas Salz oder Zimt bestreuen und durchschütteln. Ungepoppte Körner aussortieren."]]},
{"id": "bananen-quark-shake", "cat": "snack", "ty": "veggie", "kcal": 190, "t": "3 Min.", "name": "Bananen-Quark-Shake", "g": [["Zutaten", [[0.5, "", "Banane"], [100, "g", "Magerquark"], [150, "ml", "Milch (1,5 %)"], [null, "", "Zimt"]]]], "s": [["Vorbereiten", "Banane schälen und in Stücke brechen. Für einen kalten Shake die Banane vorher einfrieren."], ["Mixen", "Banane, Magerquark und Milch in den Mixer geben und ca. 30 Sekunden cremig pürieren."], ["Anpassen", "Zu dick? Etwas Milch nachgießen. Zu wenig süß? Eine reifere Banane verwenden."], ["Servieren", "In ein Glas füllen und mit Zimt bestreuen. Sofort trinken."]]},
{"id": "toskana-haehnchen-light-mit-vollkornnudeln", "cat": "abend", "ty": "haehnchen", "kcal": 470, "t": "25 Min.", "name": "Toskana-Hähnchen light mit Vollkornnudeln", "g": [["Zutaten", [[120, "g", "Hähnchenbrust (in Streifen)"], [40, "g", "Vollkornnudeln (roh)"], [50, "g", "Babyspinat"], [15, "g", "getrocknete Tomaten (nicht in Öl)"], [1, "", "Knoblauchzehe"], [50, "ml", "Milch (1,5 %)"], [30, "g", "Frischkäse light"], [1, "TL", "Olivenöl"], [10, "g", "Parmesan"], [null, "", "italienische Kräuter, Salz, Pfeffer"]]]], "s": [["Nudeln kochen", "Reichlich Salzwasser aufkochen und die Vollkornnudeln nach Packungsanweisung bissfest garen (meist ca. 10 Minuten). 3 EL Nudelwasser aufheben, dann abgießen."], ["Vorbereiten", "Hähnchen trocken tupfen und in Streifen schneiden. Knoblauch fein hacken, getrocknete Tomaten in Streifen schneiden."], ["Hähnchen braten", "Olivenöl in einer Pfanne erhitzen. Hähnchen 4–5 Minuten rundherum goldbraun braten, mit Salz und Pfeffer würzen und herausnehmen."], ["Sauce", "Knoblauch und Tomaten in der Pfanne 1 Minute andünsten. Milch und Frischkäse einrühren, bis eine glatte Sauce entsteht. Italienische Kräuter zugeben und 3 Minuten leise köcheln lassen."], ["Spinat und Käse", "Spinat unterheben und rühren, bis er zusammenfällt. Parmesan einrühren. Ist die Sauce zu dick, etwas Nudelwasser zugeben."], ["Servieren", "Hähnchen und Nudeln in die Sauce geben, alles gut durchschwenken und mit Pfeffer abschmecken."]]},
{"id": "lachs-mit-ofengemuese-und-kraeuterquark", "cat": "abend", "ty": "fisch", "kcal": 410, "t": "30 Min.", "name": "Lachs mit Ofengemüse und Kräuterquark", "g": [["Zutaten", [[120, "g", "Lachsfilet"], [0.5, "", "Paprika"], [0.5, "", "Zucchini"], [80, "g", "Champignons"], [1, "TL", "Olivenöl"], [100, "g", "Magerquark"], [null, "", "Kräuter, Thymian, Salz, Pfeffer"]]]], "s": [["Ofen vorheizen", "Backofen auf 200 °C Ober-/Unterhitze vorheizen. Ein Blech mit Backpapier auslegen."], ["Gemüse vorbereiten", "Paprika und Zucchini in mundgerechte Stücke schneiden, Champignons putzen und halbieren. Mit Olivenöl, Thymian, Salz und Pfeffer mischen und auf dem Blech verteilen."], ["Gemüse backen", "Gemüse 15 Minuten backen."], ["Lachs dazulegen", "Lachs trocken tupfen, salzen, pfeffern und zwischen das Gemüse legen. Weitere 12–15 Minuten backen, bis der Lachs gerade gar und innen noch saftig ist."], ["Kräuterquark", "Währenddessen Magerquark mit 1–2 EL Wasser glatt rühren, gehackte Kräuter unterheben und mit Salz, Pfeffer und etwas Zitronensaft abschmecken."], ["Servieren", "Lachs und Ofengemüse auf einem Teller anrichten und den Kräuterquark dazu reichen."]]},
{"id": "rindergeschnetzeltes-stroganoff-light-mit-reis", "cat": "abend", "ty": "rind", "kcal": 430, "t": "25 Min.", "name": "Rindergeschnetzeltes Stroganoff light mit Reis", "g": [["Zutaten", [[120, "g", "Rinderhüfte (in Streifen)"], [40, "g", "Reis (roh)"], [80, "g", "Champignons"], [0.25, "", "Zwiebel"], [1, "", "Gewürzgurke"], [50, "g", "saure Sahne (10 %)"], [50, "ml", "Rinderfond"], [1, "TL", "Senf"], [1, "TL", "Tomatenmark"], [1, "TL", "Öl"]]]], "s": [["Reis kochen", "Reis nach Packungsanweisung garen."], ["Vorbereiten", "Rinderhüfte quer zur Faser in dünne Streifen schneiden und trocken tupfen. Zwiebel fein würfeln, Champignons in Scheiben und die Gewürzgurke in feine Streifen schneiden."], ["Fleisch braten", "Öl in einer Pfanne sehr stark erhitzen. Fleisch darin 1 Minute scharf anbraten, sodass es innen noch rosa ist. Herausnehmen, salzen und pfeffern."], ["Pilze braten", "Zwiebel und Champignons in derselben Pfanne 4 Minuten kräftig braten. Tomatenmark und Senf zugeben und 1 Minute mitrösten."], ["Sauce", "Mit Rinderfond ablöschen, den Bratensatz vom Pfannenboden lösen und 3 Minuten köcheln lassen. Hitze reduzieren, saure Sahne und Gurkenstreifen einrühren. Ab jetzt nicht mehr kochen, sonst flockt die Sahne aus."], ["Fertigstellen", "Fleisch mit dem ausgetretenen Saft zurück in die Sauce geben, kurz erwärmen, mit Paprikapulver, Salz und Pfeffer abschmecken und mit dem Reis servieren."]]},
{"id": "bohnen-fajita-mit-paprika", "cat": "abend", "ty": "veggie", "kcal": 370, "t": "20 Min.", "name": "Bohnen-Fajita mit Paprika", "g": [["Zutaten", [[80, "g", "Kidneybohnen (Dose, abgetropft)"], [1, "", "Paprika"], [0.5, "", "Zwiebel"], [1, "", "Vollkorn-Tortilla"], [2, "EL", "Naturjoghurt (1,5 %)"], [1, "TL", "Öl"], [null, "", "Paprikapulver, Kreuzkümmel, Knoblauchpulver, Limette"]]]], "s": [["Vorbereiten", "Paprika und Zwiebel in feine Streifen schneiden. Kidneybohnen abspülen und abtropfen lassen."], ["Gemüse braten", "Öl in einer Pfanne stark erhitzen und Paprika und Zwiebel 4–5 Minuten unter Rühren braten, bis sie leichte Röstaromen haben, aber noch knackig sind."], ["Bohnen zugeben", "Bohnen, Paprikapulver, Kreuzkümmel und Knoblauchpulver zugeben und 2 Minuten mitbraten. Einige Bohnen mit dem Pfannenwender leicht zerdrücken, so wird die Füllung cremiger."], ["Abschmecken", "Mit Salz und Limettensaft abschmecken."], ["Füllen", "Tortilla in einer Pfanne ohne Fett kurz erwärmen, mit Joghurt bestreichen, die Füllung darauf verteilen und einrollen."]]},
{"id": "kabeljau-in-leichter-senfsauce-mit-kartoffeln", "cat": "abend", "ty": "fisch", "kcal": 350, "t": "25 Min.", "name": "Kabeljau in leichter Senfsauce mit Kartoffeln", "g": [["Zutaten", [[150, "g", "Kabeljaufilet"], [200, "g", "Kartoffeln"], [100, "ml", "Milch (1,5 %)"], [1, "TL", "Speisestärke"], [1, "EL", "mittelscharfer Senf"], [0.25, "", "Gurke"], [1, "EL", "Naturjoghurt"], [null, "", "Dill, Salz, Pfeffer"]]]], "s": [["Kartoffeln kochen", "Kartoffeln schälen, halbieren und in Salzwasser ca. 20 Minuten weich kochen."], ["Gurkensalat", "Währenddessen die Gurke in dünne Scheiben hobeln, leicht salzen und 5 Minuten ziehen lassen. Wasser abgießen, mit Joghurt, gehacktem Dill und Pfeffer anmachen."], ["Sauce ansetzen", "Milch in einer kleinen, breiten Pfanne erhitzen. Speisestärke mit 2 EL kaltem Wasser glatt rühren, in die heiße Milch rühren und 1 Minute köcheln lassen, bis die Sauce bindet."], ["Würzen", "Senf einrühren und mit Salz und Pfeffer abschmecken. Nach Wunsch etwas Dill hineingeben."], ["Fisch garen", "Kabeljau salzen und in die Sauce legen. Zugedeckt bei niedriger Hitze ca. 8 Minuten gar ziehen lassen. Die Sauce darf dabei nicht kochen, sonst wird der Fisch trocken."], ["Servieren", "Kartoffeln abgießen, ausdampfen lassen und mit dem Fisch in Senfsauce und dem Gurkensalat anrichten."]]},
{"id": "haehnchen-gemuese-curry-light", "cat": "abend", "ty": "haehnchen", "kcal": 400, "t": "25 Min.", "name": "Hähnchen-Gemüse-Curry light", "g": [["Zutaten", [[120, "g", "Hähnchenbrust (gewürfelt)"], [40, "g", "Jasminreis (roh)"], [0.5, "", "Paprika"], [80, "g", "Brokkoli"], [1, "", "Karotte"], [100, "ml", "Kokosmilch light"], [1, "TL", "Currypaste"], [null, "", "Ingwer, Limettensaft"]]]], "s": [["Reis kochen", "Jasminreis nach Packungsanweisung garen."], ["Vorbereiten", "Hähnchen würfeln. Paprika in Streifen, Karotte in dünne Scheiben schneiden, Brokkoli in kleine Röschen teilen. Ingwer schälen und reiben."], ["Anrösten", "Currypaste und Ingwer in einer beschichteten Pfanne oder einem Wok bei mittlerer Hitze 1 Minute anrösten, bis es duftet."], ["Hähnchen braten", "Hähnchenwürfel zugeben und 3 Minuten rundherum anbraten."], ["Köcheln", "Karotte, Brokkoli und Paprika zugeben, Kokosmilch angießen und 8–10 Minuten bei mittlerer Hitze köcheln lassen, bis das Gemüse bissfest und das Hähnchen gar ist. Ist es zu dick, einen Schluck Wasser zugeben."], ["Abschmecken", "Mit Limettensaft und etwas Salz abschmecken und mit dem Reis servieren."]]},
{"id": "gnocchi-gemuese-pfanne-light", "cat": "abend", "ty": "veggie", "kcal": 350, "t": "20 Min.", "name": "Gnocchi-Gemüse-Pfanne light", "g": [["Zutaten", [[150, "g", "Gnocchi (Kühlregal)"], [100, "g", "Kirschtomaten"], [50, "g", "Babyspinat"], [30, "g", "Mozzarella light"], [1, "TL", "Olivenöl"], [1, "", "Knoblauchzehe"], [null, "", "Basilikum, Salz, Pfeffer"]]]], "s": [["Vorbereiten", "Knoblauch fein hacken, Kirschtomaten halbieren, Spinat waschen und abtropfen lassen."], ["Gnocchi braten", "Olivenöl in einer beschichteten Pfanne erhitzen. Gnocchi direkt aus der Packung (ohne Vorkochen) hineingeben und 6–8 Minuten bei mittlerer Hitze braten, dabei öfter wenden, bis sie rundherum goldbraun und knusprig sind."], ["Tomaten", "Knoblauch und Tomaten zugeben und 3 Minuten mitbraten, bis die Tomaten leicht aufplatzen."], ["Spinat", "Spinat unterheben und rühren, bis er zusammengefallen ist. Mit Salz und Pfeffer würzen."], ["Überbacken", "Mozzarella in kleine Stücke zupfen, auf den Gnocchi verteilen, Deckel auflegen und 2 Minuten schmelzen lassen. Mit Basilikum bestreuen."]]},
{"id": "schweinefilet-mit-brokkoli-und-petersilienkartoffeln", "cat": "abend", "ty": "schwein", "kcal": 330, "t": "30 Min.", "name": "Schweinefilet mit Brokkoli und Petersilienkartoffeln", "g": [["Zutaten", [[120, "g", "Schweinefilet"], [150, "g", "Brokkoli"], [150, "g", "Kartoffeln"], [1, "TL", "Öl"], [null, "", "Petersilie, Muskat, Salz, Pfeffer"]]]], "s": [["Kartoffeln kochen", "Kartoffeln schälen und in Salzwasser ca. 20 Minuten weich kochen."], ["Fleisch vorbereiten", "Schweinefilet 15 Minuten vor dem Braten aus dem Kühlschrank nehmen, Sehnen entfernen und in 2–3 cm dicke Medaillons schneiden. Trocken tupfen."], ["Medaillons braten", "Öl in einer Pfanne stark erhitzen und die Medaillons von jeder Seite 2–3 Minuten braten. Salzen, pfeffern und in Alufolie gewickelt 5 Minuten ruhen lassen. So bleiben sie saftig."], ["Brokkoli garen", "Brokkoli in Röschen teilen und in wenig Salzwasser ca. 5 Minuten bissfest garen. Abgießen und mit etwas Muskat würzen."], ["Servieren", "Kartoffeln abgießen, mit gehackter Petersilie bestreuen und mit Medaillons und Brokkoli anrichten. Den Fleischsaft aus der Folie darüberträufeln."]]},
{"id": "gefuellte-paprika-mit-couscous-und-feta", "cat": "abend", "ty": "veggie", "kcal": 270, "t": "40 Min.", "name": "Gefüllte Paprika mit Couscous und Feta", "g": [["Zutaten", [[1, "", "große Paprika"], [30, "g", "Couscous"], [60, "ml", "heiße Gemüsebrühe"], [30, "g", "Feta"], [0.25, "", "Zucchini"], [150, "g", "passierte Tomaten"], [null, "", "Oregano, Salz, Pfeffer"]]]], "s": [["Ofen vorheizen", "Backofen auf 200 °C Ober-/Unterhitze vorheizen."], ["Couscous quellen", "Couscous in eine Schüssel geben, mit der heißen Gemüsebrühe übergießen, abdecken und 5 Minuten quellen lassen. Dann mit einer Gabel auflockern."], ["Füllung", "Zucchini fein würfeln. Mit dem Couscous, der Hälfte des zerbröselten Fetas, Oregano, Salz und Pfeffer mischen."], ["Paprika füllen", "Paprika längs halbieren, Kerne und weiße Häute entfernen. Die Hälften mit der Couscous-Mischung füllen und leicht andrücken."], ["Sauce", "Passierte Tomaten mit Salz, Pfeffer und etwas Oregano würzen und in eine kleine Auflaufform geben. Die gefüllten Paprika hineinsetzen."], ["Backen", "Restlichen Feta darüberstreuen und 25–30 Minuten backen, bis die Paprika weich und der Feta leicht gebräunt ist."]]},
{"id": "asiatische-tofu-gemuesesuppe", "cat": "abend", "ty": "veggie", "kcal": 300, "t": "20 Min.", "name": "Asiatische Tofu-Gemüsesuppe", "g": [["Zutaten", [[120, "g", "Naturtofu"], [30, "g", "Reisnudeln"], [0.5, "", "Pak Choi"], [80, "g", "Champignons"], [1, "Stück", "Ingwer (2 cm)"], [350, "ml", "Gemüsebrühe"], [1, "EL", "Sojasauce"]]]], "s": [["Tofu vorbereiten", "Tofu aus der Packung nehmen, gut abtropfen lassen und mit Küchenpapier trocken drücken. In 2 cm große Würfel schneiden."], ["Gemüse schneiden", "Champignons in Scheiben schneiden. Pak Choi waschen, den Strunk abschneiden, die Stiele in Stücke und die Blätter in Streifen schneiden. Ingwer schälen und in feine Scheiben schneiden."], ["Brühe ansetzen", "Gemüsebrühe mit dem Ingwer aufkochen und 5 Minuten köcheln lassen, damit sie Aroma bekommt."], ["Einlage garen", "Reisnudeln, Champignons, Pak-Choi-Stiele und Tofu zugeben und 4 Minuten ziehen lassen. Dann die Pak-Choi-Blätter zugeben und 1 Minute mitgaren."], ["Abschmecken", "Mit Sojasauce abschmecken. Nach Wunsch mit Frühlingszwiebeln, Chili oder einem Spritzer Limette servieren."]]},
{"id": "blumenkohl-kichererbsen-curry", "cat": "abend", "ty": "veggie", "kcal": 300, "t": "30 Min.", "name": "Blumenkohl-Kichererbsen-Curry", "g": [["Zutaten", [[200, "g", "Blumenkohl"], [80, "g", "Kichererbsen (Dose)"], [30, "g", "Basmatireis (roh)"], [50, "ml", "Kokosmilch light"], [100, "ml", "Gemüsebrühe"], [1, "TL", "Currypaste"], [30, "g", "Babyspinat"]]]], "s": [["Reis kochen", "Basmatireis nach Packungsanweisung garen."], ["Vorbereiten", "Blumenkohl in kleine Röschen teilen. Kichererbsen abspülen und abtropfen lassen."], ["Anrösten", "Currypaste in einem Topf bei mittlerer Hitze 1 Minute anrösten."], ["Köcheln", "Kokosmilch und Gemüsebrühe zugießen und aufkochen. Blumenkohl und Kichererbsen zugeben und zugedeckt 12 Minuten köcheln lassen, bis der Blumenkohl gar, aber noch bissfest ist."], ["Spinat", "Spinat unterheben und 1 Minute mitziehen lassen, bis er zusammenfällt. Mit Salz und nach Wunsch einem Spritzer Zitrone abschmecken."], ["Servieren", "Curry mit dem Reis anrichten."]]},
{"id": "linsen-bolognese-mit-vollkornspaghetti", "cat": "abend", "ty": "veggie", "kcal": 430, "t": "25 Min.", "name": "Linsen-Bolognese mit Vollkornspaghetti", "g": [["Zutaten", [[50, "g", "Vollkornspaghetti"], [30, "g", "rote Linsen"], [150, "g", "passierte Tomaten"], [0.5, "", "Karotte"], [0.25, "", "Zwiebel"], [0.25, "", "Zucchini"], [1, "TL", "Olivenöl"], [10, "g", "Parmesan"], [null, "", "Oregano, Salz, Pfeffer"]]]], "s": [["Gemüse schneiden", "Zwiebel, Karotte und Zucchini sehr fein würfeln. Je feiner, desto mehr erinnert die Sauce an klassische Bolognese."], ["Andünsten", "Olivenöl in einem Topf erhitzen und das Gemüse bei mittlerer Hitze 4 Minuten andünsten."], ["Sauce köcheln", "Linsen abspülen und mit den passierten Tomaten, 100 ml Wasser und Oregano zugeben. Aufkochen und 12–15 Minuten köcheln lassen, bis die Linsen weich sind. Bei Bedarf etwas Wasser nachgießen."], ["Nudeln kochen", "Währenddessen die Spaghetti in reichlich Salzwasser nach Packungsanweisung bissfest garen und abgießen."], ["Servieren", "Sauce mit Salz und Pfeffer abschmecken, über die Spaghetti geben und mit Parmesan bestreuen."]]},
{"id": "spinat-feta-frittata-mit-salat", "cat": "abend", "ty": "veggie", "kcal": 290, "t": "20 Min.", "name": "Spinat-Feta-Frittata mit Salat", "g": [["Zutaten", [[2, "", "Eier"], [60, "g", "Babyspinat"], [0.5, "", "Paprika"], [20, "g", "Feta"], [1, "TL", "Olivenöl"], [1, "Handvoll", "Blattsalat"], [null, "", "Zitronensaft, Salz, Pfeffer"]]]], "s": [["Vorbereiten", "Paprika würfeln, Spinat waschen und abtropfen lassen. Eier mit Salz und Pfeffer verquirlen."], ["Gemüse braten", "Olivenöl in einer kleinen beschichteten Pfanne erhitzen. Paprika 3 Minuten braten, dann Spinat zugeben und rühren, bis er zusammenfällt."], ["Stocken lassen", "Gemüse gleichmäßig verteilen, die Eier darübergießen und den Feta darüberbröseln. Deckel auflegen und bei niedriger Hitze 8–10 Minuten stocken lassen, bis die Oberfläche fest ist."], ["Salat", "Währenddessen den Blattsalat waschen, trocken schleudern und mit Zitronensaft, Salz und Pfeffer anmachen."], ["Servieren", "Frittata aus der Pfanne gleiten lassen, in Stücke schneiden und mit dem Salat servieren. Schmeckt auch kalt am nächsten Tag."]]},
{"id": "rindersteak-mit-buntem-salat", "cat": "abend", "ty": "rind", "kcal": 260, "t": "20 Min.", "name": "Rindersteak mit buntem Salat", "g": [["Zutaten", [[150, "g", "Rinderhüftsteak"], [1, "Handvoll", "Blattsalat"], [0.25, "", "Gurke"], [6, "", "Kirschtomaten"], [0.5, "", "Paprika"], [1, "TL", "Olivenöl"], [1, "TL", "heller Balsamico"], [0.5, "TL", "Senf"], [0.5, "TL", "Honig"]]]], "s": [["Steak temperieren", "Steak 30 Minuten vor dem Braten aus dem Kühlschrank nehmen und mit Küchenpapier trocken tupfen."], ["Salat vorbereiten", "Blattsalat waschen und trocken schleudern. Gurke in Scheiben, Paprika in Streifen schneiden, Kirschtomaten halbieren."], ["Dressing", "Olivenöl, Balsamico, Senf und Honig mit Salz und Pfeffer glatt rühren."], ["Steak braten", "Eine beschichtete oder gusseiserne Pfanne sehr stark erhitzen. Steak ohne Fett 2–3 Minuten pro Seite braten (medium). Nicht zwischendurch bewegen, damit eine schöne Kruste entsteht."], ["Ruhen lassen", "Steak auf einem Brett locker mit Alufolie abdecken und 5 Minuten ruhen lassen. Erst dann mit grobem Salz und Pfeffer würzen und schräg in Streifen schneiden."], ["Servieren", "Salat mit dem Dressing mischen und mit den Steakstreifen anrichten."]]},
{"id": "beeren-quark-creme", "cat": "dessert", "ty": "veggie", "kcal": 155, "t": "10 Min.", "name": "Beeren-Quark-Creme", "g": [["Zutaten", [[125, "g", "Magerquark"], [40, "g", "Naturjoghurt (1,5 %)"], [1, "TL", "Honig"], [75, "g", "Beeren"], [null, "", "etwas Vanille"]]]], "s": [["Creme rühren", "Magerquark, Joghurt, Honig und Vanille in einer Schüssel cremig rühren."], ["Beeren vorbereiten", "Beeren waschen und abtropfen lassen (TK-Beeren vorher auftauen). Etwa die Hälfte mit einer Gabel leicht zerdrücken, so entsteht eine fruchtige Sauce."], ["Schichten", "Abwechselnd Creme und zerdrückte Beeren in ein Glas schichten."], ["Garnieren", "Mit den ganzen Beeren abschließen. Nach Wunsch 15 Minuten kühlen, dann schmeckt es besonders frisch."]]},
{"id": "bratapfel-mit-walnuessen-und-zimt", "cat": "dessert", "ty": "veggie", "kcal": 180, "t": "30 Min.", "name": "Bratapfel mit Walnüssen und Zimt", "g": [["Zutaten", [[1, "", "säuerlicher Apfel"], [10, "g", "Walnüsse (gehackt)"], [5, "g", "Rosinen"], [0.5, "TL", "Honig"], [null, "", "Zimt"]]]], "s": [["Ofen vorheizen", "Backofen auf 180 °C Ober-/Unterhitze vorheizen."], ["Apfel vorbereiten", "Apfel waschen und das Kerngehäuse mit einem Apfelausstecher oder einem kleinen Messer großzügig herausschneiden. Den Boden dabei nicht durchstechen. Einen schmalen Deckel abschneiden."], ["Füllung", "Walnüsse, Rosinen, Honig und Zimt mischen und fest in den Apfel drücken. Deckel wieder aufsetzen."], ["Backen", "Apfel in eine kleine ofenfeste Form setzen, 2 EL Wasser angießen und ca. 25 Minuten backen, bis er weich ist und die Schale leicht aufplatzt."], ["Servieren", "Warm servieren. Ein Klecks Naturjoghurt passt gut dazu."]]},
{"id": "schoko-bananen-eis", "cat": "dessert", "ty": "veggie", "kcal": 150, "t": "5 Min. + Gefrieren", "name": "Schoko-Bananen-Eis", "g": [["Zutaten", [[1, "", "reife Banane"], [1, "TL", "Backkakao"], [2, "EL", "Milch"], [5, "g", "Zartbitterschokolade (geraspelt)"]]]], "s": [["Einfrieren", "Banane schälen, in Scheiben schneiden und auf einem Teller mit Backpapier mindestens 4 Stunden einfrieren. Am besten immer ein paar gefrorene Bananen vorrätig haben."], ["Antauen lassen", "Gefrorene Bananenscheiben 5 Minuten bei Raumtemperatur antauen lassen, dann lassen sie sich leichter pürieren."], ["Pürieren", "Banane mit Kakao und Milch im Mixer oder mit einem kräftigen Stabmixer pürieren. Zwischendurch die Masse vom Rand schieben, bis eine cremige Eiskonsistenz entsteht."], ["Servieren", "Sofort in eine Schale füllen und mit Schokoraspeln bestreuen. Für festere Konsistenz noch 20 Minuten ins Gefrierfach stellen."]]},
{"id": "tiramisu-light-im-glas", "cat": "dessert", "ty": "veggie", "kcal": 230, "t": "15 Min. + 2 Std.", "name": "Tiramisu light im Glas", "g": [["Zutaten", [[80, "g", "Magerquark"], [20, "g", "Mascarpone"], [1, "TL", "Honig"], [3, "", "Löffelbiskuits"], [40, "ml", "kalter Espresso"], [0.5, "TL", "Backkakao"]]]], "s": [["Creme rühren", "Magerquark, Mascarpone und Honig in einer Schüssel glatt und cremig rühren."], ["Biskuits tränken", "Espresso in einen tiefen Teller geben. Löffelbiskuits halbieren und jeweils nur kurz (1–2 Sekunden) in den Espresso tauchen, damit sie nicht zerfallen."], ["Schichten", "Eine Lage Biskuits in ein Glas legen, Creme daraufgeben und wiederholen. Mit einer Schicht Creme abschließen."], ["Kühlen", "Mindestens 2 Stunden im Kühlschrank durchziehen lassen."], ["Bestäuben", "Kurz vor dem Servieren den Kakao durch ein kleines Sieb darüberstäuben."]]},
{"id": "milchreis-mit-kirschen", "cat": "dessert", "ty": "veggie", "kcal": 260, "t": "35 Min.", "name": "Milchreis mit Kirschen", "g": [["Zutaten", [[30, "g", "Milchreis"], [180, "ml", "Milch (1,5 %)"], [1, "TL", "Zucker"], [80, "g", "Sauerkirschen (Glas, abgetropft)"], [null, "", "Zimt"]]]], "s": [["Aufkochen", "Milch mit Zucker und einer Prise Salz in einem kleinen Topf aufkochen. Topf mit kaltem Wasser ausspülen, dann brennt die Milch weniger an."], ["Reis quellen", "Milchreis einrühren, Hitze auf die kleinste Stufe reduzieren und den Reis zugedeckt 25–30 Minuten quellen lassen. Alle paar Minuten umrühren, damit nichts am Boden ansetzt."], ["Konsistenz prüfen", "Der Reis ist fertig, wenn die Körner weich sind und die Masse cremig ist. Ist er zu fest, einen Schluck Milch unterrühren."], ["Kirschen", "Kirschen abtropfen lassen und nach Wunsch in einem kleinen Topf mit 2 EL Kirschsaft kurz erwärmen."], ["Servieren", "Milchreis in eine Schale füllen, Kirschen darauf verteilen und mit Zimt bestreuen. Schmeckt warm und kalt."]]},
{"id": "apfel-crumble", "cat": "dessert", "ty": "veggie", "kcal": 230, "t": "30 Min.", "name": "Apfel-Crumble", "g": [["Zutaten", [[1, "", "Apfel"], [15, "g", "Haferflocken"], [5, "g", "Butter"], [1, "TL", "Ahornsirup"], [5, "g", "gehackte Mandeln"], [null, "", "Zimt"]]]], "s": [["Ofen vorheizen", "Backofen auf 180 °C Ober-/Unterhitze vorheizen."], ["Äpfel vorbereiten", "Apfel waschen, entkernen und in kleine Würfel schneiden. Mit Zimt mischen und in eine kleine Auflaufform oder ofenfeste Schale geben."], ["Streusel", "Haferflocken, kalte Butter in kleinen Stückchen, Ahornsirup und Mandeln in einer Schüssel mit den Fingern zu Streuseln verreiben."], ["Backen", "Streusel gleichmäßig über die Äpfel verteilen und 20–25 Minuten backen, bis die Streusel goldbraun sind und die Äpfel an den Rändern blubbern."], ["Servieren", "5 Minuten abkühlen lassen und warm servieren. Ein Löffel Joghurt passt gut dazu."]]},
{"id": "mango-joghurt-creme-mit-limette", "cat": "dessert", "ty": "veggie", "kcal": 125, "t": "5 Min.", "name": "Mango-Joghurt-Creme mit Limette", "g": [["Zutaten", [[150, "g", "Naturjoghurt (1,5 %)"], [80, "g", "Mango"], [null, "", "Limettenabrieb, Minze"]]]], "s": [["Mango vorbereiten", "Mango schälen, das Fruchtfleisch vom Kern schneiden und würfeln."], ["Pürieren", "Die Hälfte der Mangowürfel mit einer Gabel oder dem Stabmixer fein pürieren."], ["Creme", "Joghurt glatt rühren und das Mangopüree locker unterziehen, sodass ein Marmoreffekt entsteht."], ["Anrichten", "Creme in ein Glas füllen, restliche Mangowürfel darauf verteilen und mit Limettenabrieb und frischer Minze garnieren."]]},
{"id": "zimt-birne-aus-dem-ofen", "cat": "dessert", "ty": "veggie", "kcal": 165, "t": "25 Min.", "name": "Zimt-Birne aus dem Ofen", "g": [["Zutaten", [[1, "", "Birne"], [0.5, "TL", "Honig"], [50, "g", "Naturjoghurt (1,5 %)"], [5, "g", "Mandelblättchen"], [null, "", "Zimt"]]]], "s": [["Ofen vorheizen", "Backofen auf 180 °C Ober-/Unterhitze vorheizen."], ["Birne vorbereiten", "Birne waschen, längs halbieren und das Kerngehäuse mit einem Teelöffel herauslösen."], ["Backen", "Birnenhälften mit der Schnittfläche nach oben in eine kleine Form legen, mit Honig beträufeln und mit Zimt bestreuen. Ca. 20 Minuten backen, bis sie weich sind."], ["Mandeln rösten", "Mandelblättchen in einer Pfanne ohne Fett 1–2 Minuten goldbraun rösten."], ["Servieren", "Birnen warm mit dem Joghurt anrichten und mit den Mandelblättchen bestreuen."]]},
{"id": "schoko-skyr-mousse", "cat": "dessert", "ty": "veggie", "kcal": 150, "t": "5 Min.", "name": "Schoko-Skyr-Mousse", "g": [["Zutaten", [[150, "g", "Skyr"], [1, "TL", "Backkakao"], [1, "TL", "Honig"], [5, "g", "Zartbitterschokolade (geraspelt)"]]]], "s": [["Kakao auflösen", "Kakao mit dem Honig und 1 EL heißem Wasser glatt rühren. So entstehen keine Klümpchen."], ["Mousse rühren", "Skyr zugeben und mit einem Schneebesen kräftig aufschlagen, bis die Masse luftig und gleichmäßig braun ist."], ["Kühlen", "In ein Glas füllen und nach Wunsch 15 Minuten kalt stellen."], ["Garnieren", "Mit Schokoraspeln bestreuen. Ein paar Himbeeren passen hervorragend dazu."]]},
{"id": "erdbeeren-mit-balsamico-und-minze", "cat": "dessert", "ty": "veggie", "kcal": 100, "t": "5 Min.", "name": "Erdbeeren mit Balsamico und Minze", "g": [["Zutaten", [[200, "g", "Erdbeeren"], [1, "TL", "Balsamico-Creme"], [2, "EL", "Naturjoghurt (1,5 %)"], [null, "", "frische Minze"]]]], "s": [["Erdbeeren vorbereiten", "Erdbeeren waschen, erst dann den Strunk entfernen (sonst saugen sie sich mit Wasser voll) und vierteln."], ["Marinieren", "Erdbeeren mit der Balsamico-Creme vorsichtig mischen und 10 Minuten ziehen lassen. Der Balsamico verstärkt das Erdbeeraroma."], ["Minze", "Minzblätter fein schneiden."], ["Servieren", "Erdbeeren in eine Schale geben, Joghurt daraufsetzen und mit Minze und etwas frisch gemahlenem Pfeffer bestreuen."]]},
{"id": "schnelles-beeren-sorbet", "cat": "dessert", "ty": "veggie", "kcal": 105, "t": "5 Min.", "name": "Schnelles Beeren-Sorbet", "g": [["Zutaten", [[150, "g", "TK-Beeren"], [50, "g", "Naturjoghurt (1,5 %)"], [1, "TL", "Honig"]]]], "s": [["Antauen lassen", "TK-Beeren 3–5 Minuten bei Raumtemperatur antauen lassen."], ["Pürieren", "Beeren mit Joghurt und Honig in einen leistungsstarken Mixer oder ein hohes Gefäß geben und pürieren, bis eine cremige, gleichmäßige Masse entsteht. Zwischendurch mit einem Löffel nachschieben."], ["Abschmecken", "Zu sauer? Etwas mehr Honig zugeben. Zu fest? 1 EL Joghurt ergänzen."], ["Servieren", "Sofort servieren, solange es eisig ist. Für Kugeln 20 Minuten ins Gefrierfach stellen."]]},
{"id": "kirsch-quark-auflauf", "cat": "dessert", "ty": "veggie", "kcal": 240, "t": "30 Min.", "name": "Kirsch-Quark-Auflauf", "g": [["Zutaten", [[100, "g", "Magerquark"], [1, "", "Ei"], [10, "g", "Grieß"], [1, "TL", "Honig"], [60, "g", "Kirschen (Glas oder TK)"]]]], "s": [["Ofen vorheizen", "Backofen auf 180 °C Ober-/Unterhitze vorheizen und eine kleine Auflaufform leicht einfetten."], ["Masse rühren", "Magerquark, Ei, Grieß und Honig glatt verrühren. Nach Wunsch etwas Zitronenabrieb oder Vanille zugeben. 5 Minuten quellen lassen."], ["Kirschen", "Kirschen gut abtropfen lassen (TK-Kirschen vorher auftauen) und in der Form verteilen."], ["Backen", "Quarkmasse über die Kirschen streichen und ca. 25 Minuten backen, bis die Oberfläche goldgelb und fest ist."], ["Servieren", "Kurz abkühlen lassen. Schmeckt warm und kalt."]]},
{"id": "gebratene-ananas-mit-zimt", "cat": "dessert", "ty": "veggie", "kcal": 125, "t": "10 Min.", "name": "Gebratene Ananas mit Zimt", "g": [["Zutaten", [[150, "g", "Ananas"], [50, "g", "Naturjoghurt (1,5 %)"], [0.5, "TL", "Kokosraspel"], [null, "", "Zimt"]]]], "s": [["Ananas schneiden", "Ananas schälen, den Strunk entfernen und in ca. 1 cm dicke Scheiben schneiden."], ["Braten", "Eine beschichtete Pfanne ohne Fett stark erhitzen. Ananasscheiben von jeder Seite 2–3 Minuten braten, bis sie goldbraun karamellisiert sind."], ["Würzen", "Noch in der Pfanne mit Zimt bestreuen."], ["Kokos rösten", "Kokosraspel kurz in der heißen Pfanne anrösten."], ["Servieren", "Ananas warm mit dem Joghurt anrichten und mit den Kokosraspeln bestreuen."]]},
{"id": "bananen-hafer-kekse", "cat": "dessert", "ty": "veggie", "kcal": 150, "t": "20 Min.", "name": "Bananen-Hafer-Kekse", "g": [["Zutaten", [[0.5, "", "reife Banane"], [20, "g", "zarte Haferflocken"], [5, "g", "Zartbitterschokolade (gehackt)"], [null, "", "Zimt"]]]], "s": [["Ofen vorheizen", "Backofen auf 180 °C Ober-/Unterhitze vorheizen und ein Blech mit Backpapier auslegen."], ["Teig", "Banane mit einer Gabel fein zerdrücken. Je reifer die Banane, desto süßer die Kekse. Haferflocken, gehackte Schokolade und Zimt unterrühren."], ["Quellen lassen", "Teig 5 Minuten ruhen lassen, damit die Haferflocken die Feuchtigkeit aufnehmen."], ["Formen", "Mit einem Teelöffel 4 kleine Häufchen auf das Blech setzen und flach drücken. Die Kekse laufen nicht auseinander."], ["Backen", "12–15 Minuten backen, bis die Ränder goldbraun sind. Auf dem Blech abkühlen lassen, dabei werden sie fester."]]}
